for d in TOPICS.values():
    for u in d['units'].values():
        for b in u['blocks']:
            b['text']=re.sub(r'\s*\(ITEM-6136-[^)]+\)','',b['text'])
for n in [25,27,28,29,30,31,32]:
    i=item('8.1',n)
    criteria={25:'identify a public resource/service action and link implementation to usable access',27:'link greater safety to continued work, learning or participation while retaining accountable protection',28:'link suitable finance to obtaining productive inputs and a viable use or repayment condition',29:'link a maintained, usable network to actual service or market access',30:'link education/social provision to capability or well-being and a delivery/access condition',31:'link local information to a more responsive decision with adequate resources and accountability',32:'identify a specific implementation barrier and explain how it limits the intended service or benefit'}[n]
    i['marking_guidance']=['Reason, up to '+str(i['mark_tariff'])+' marks: '+criteria+'. Credit a clear contribution and its relevant explanation; disconnected lists or stereotypes are insufficient.','Original indicative practice guidance; not an official mark scheme.']

actions=[];revisions=[]
for t,d in TOPICS.items():
    oldledger=read(OUT/'baseline'/d['lp'].relative_to(WS))
    oldclaims={c['claim_id']:c for c in oldledger['claims']}
    changed_claims={}
    for c in d['ledger']['claims']:
        old=oldclaims[c['claim_id']]
        if c['text']!=old['text']:
            c['revision']=old.get('revision',1)+1;c['revised_at']='2026-10-21'
            changed_claims[c['claim_id']]=c['revision']
            revisions.append({'claim_id':c['claim_id'],'before':old,'after':copy.deepcopy(c)})
    artefacts=d['items']['items']+[b for u in d['units'].values() for b in u['blocks']]
    olditems=read(OUT/'baseline'/d['ip'].relative_to(WS))['items']
    oldarts={i['item_id']:i for i in olditems}
    for name in d['units']:
        oldarts.update({b['block_id']:b for b in read(OUT/'baseline'/d['td'].relative_to(WS)/'content-units'/name)['blocks']})
    for x in artefacts:
        aid=x.get('item_id',x.get('block_id'));old=oldarts[aid]
        h0=hashlib.sha256(_artefact_text(old).encode()).hexdigest();h1=hashlib.sha256(_artefact_text(x).encode()).hexdigest()
        cited=set(x.get('claim_ids',[]))&set(changed_claims)
        if cited:
            x['claims_seen'].update({cid:changed_claims[cid] for cid in cited})
            if h0==h1:
                x['prior_hash']=old.get('authored_hash',h0)
                x['reviewed_unchanged']='Re-read against the expanded SDG/policy-label claim: this artefact remains accurate for its original concept or supplied case and does not rely on, contradict or claim the newly added examples.'
        if h0!=h1:actions.append({'artefact_id':aid,'before_text_sha256':h0,'after_text_sha256':h1})
    for name,u in d['units'].items():
        u['word_count']=sum(len((b['heading']+' '+b['text']).split()) for b in u['blocks'])
        assert u['word_count']<=u['word_budget']['max'],(u['unit_id'],u['word_count'])
        dump(d['td']/'content-units'/name,u)
    dump(d['ip'],d['items']);dump(d['lp'],d['ledger'])
    if any(a['artefact_id'].startswith(('ITEM-6136-'+t+'-','BLK-6136-'+t+'.')) for a in actions):
        d['notes'].setdefault('deviations',[]).append({'from':'Third-review learner-text and marking-guide defects R3-01–R3-10','to':'Developed explanations, distinct worked prose, aligned facts/guidance and source-backed goal/pillar practice within existing slots and tariffs.','why':'Jeremy authorised fixes on 2026-10-21. Existing three-mark 2.2-P02(a) now practises describing three HPP pillars with source interpretation; 1.2-P01(a) practises two sustainable-development pillars. No added slots or changed labels.'})
        d['notes']['post_review_status']='Third-review repairs applied by Codex; see review/repairs/round3/validation.json for local checks. No fourth independent review authorised.'
        dump(d['td']/'authoring_notes.json',d['notes'])
dump(OUT/'actions.json',{'author':'Codex','date':'2026-10-21','findings':['R3-'+str(n).zfill(2) for n in range(1,11)],'rewritten_card_paste_blocks':rewritten,'changed_artefacts':actions,'claim_revisions':revisions,'claude_contacted':False,'network_research':False})
print(json.dumps({'rewritten_card_paste_blocks':len(rewritten),'changed_artefacts':len(actions),'claim_revisions':len(revisions)}))
